/** This file contains utility functions for generating random numbers. */

import { LcgConstants } from '../constants';
import { Lcg } from '../types';

/**
 * The function createLcg takes a seed number and returns a linear congruential generator (LCG)
 * function. This allow us to lazily generate random numbers.
 * @param {number} seed Represents a number that is used to initialize the linear congruential
 * generator (LCG). It determines the starting point of the sequence of random numbers generated by
 * the LCG.
 * @returns {function(): Lcf} A function of type `Lcg`. The function can be used to lazily generate
 * random numbers.
 */
const createLcg =
  (seed: number): Lcg =>
  () =>
    // The LCG formula.
    (LcgConstants.A * seed + LcgConstants.C) % LcgConstants.M;

/**
 * The function `scaleNumber` takes a number `num` and scales it to a number within given range
 * `start` to `end` inclusive.
 * @param {number} num Represents the number that you want to scale.
 * @param {number} start Represents the starting value of the range you want to scale the number to.
 * @param {number} end Represents the upper bound of the desired range for scaling the number.
 */
const scaleNumber = (num: number, start: number, end: number) =>
  Math.round(((end - start) * num) / (LcgConstants.M - 1) + start);

/**
 * The `scaleFloat` function takes a number `num` and scales it to a float within given range
 * `start` to `end` inclusive.
 * @param {number} num Represents the number that you want to scale.
 * @param {number} start Represents the starting value of the range you want to scale the number to.
 * @param {number} end Represents the upper bound of the desired range for scaling the number.
 */
const scaleFloat = (num: number, start: number, end: number) =>
  ((end - start) * num) / (LcgConstants.M - 1) + start;

export { createLcg, scaleFloat, scaleNumber };
